<form class="card mb-5 flex flex-wrap items-end gap-3 p-4"><input type="hidden" name="route" value="reconciliation"><label><span class="label">Período</span><select class="field" name="period"><option value="week" <?=($_GET['period']??'week')==='week'?'selected':''?>>Semana</option><option value="fortnight" <?=($_GET['period']??'')==='fortnight'?'selected':''?>>Quinzena</option><option value="current" <?=($_GET['period']??'')==='current'?'selected':''?>>Mês</option><option value="custom" <?=($_GET['period']??'')==='custom'?'selected':''?>>Personalizado</option></select></label><label><span class="label">De</span><input class="field" type="date" name="start" value="<?=e($start)?>"></label><label><span class="label">Até</span><input class="field" type="date" name="end" value="<?=e($end)?>"></label><button class="btn btn-primary">Aplicar</button></form>
<?php $forecast=$totals['receivable']-$totals['payable'];$realized=$totals['realized_in']-$totals['realized_out']; ?>
<section class="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="card p-5"><p class="text-sm text-slate-500">Total a pagar</p><p class="mt-2 text-2xl font-bold text-red-600"><?=money($totals['payable'])?></p></div><div class="card p-5"><p class="text-sm text-slate-500">Total a receber</p><p class="mt-2 text-2xl font-bold text-emerald-600"><?=money($totals['receivable'])?></p></div><div class="card p-5 <?=$forecast<0?'border-red-400 bg-red-50 dark:bg-red-950/30':''?>"><p class="text-sm text-slate-500">Saldo previsto</p><p class="mt-2 text-2xl font-bold <?=$forecast<0?'text-red-600':'text-teal-600'?>"><?=money($forecast)?></p></div><div class="card p-5"><p class="text-sm text-slate-500">Saldo realizado</p><p class="mt-2 text-2xl font-bold"><?=money($realized)?></p></div></section>
<section class="mb-5 grid gap-4 xl:grid-cols-2"><div class="card overflow-hidden"><div class="border-b border-slate-200 p-4 dark:border-slate-800"><h2 class="font-semibold text-red-600">Saídas do período</h2></div><div class="max-h-72 overflow-auto"><?php foreach($payables as $m):?><div class="flex items-center justify-between border-b border-slate-100 px-4 py-3 text-sm last:border-0 dark:border-slate-800"><div><p class="font-medium"><?=e($m['description'])?></p><p class="text-xs text-slate-500"><?=br_date($m['due_date'])?> · <?=e(ucfirst($m['status']))?></p></div><b><?=money(abs((float)$m['expected']))?></b></div><?php endforeach;?><?php if(!$payables):?><p class="p-5 text-sm text-slate-500">Nenhuma saída.</p><?php endif;?></div></div><div class="card overflow-hidden"><div class="border-b border-slate-200 p-4 dark:border-slate-800"><h2 class="font-semibold text-emerald-600">Entradas do período</h2></div><div class="max-h-72 overflow-auto"><?php foreach($receivables as $m):?><div class="flex items-center justify-between border-b border-slate-100 px-4 py-3 text-sm last:border-0 dark:border-slate-800"><div><p class="font-medium"><?=e($m['description'])?></p><p class="text-xs text-slate-500"><?=br_date($m['due_date'])?> · <?=e(ucfirst($m['status']))?></p></div><b><?=money($m['expected'])?></b></div><?php endforeach;?><?php if(!$receivables):?><p class="p-5 text-sm text-slate-500">Nenhuma entrada.</p><?php endif;?></div></div></section>
<div class="card table-wrap"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold">Movimentações consolidadas</h2><p class="text-xs text-slate-500">Ordenadas por vencimento, com saldo previsto acumulado.</p></div><table class="data-table"><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Previsto</th><th>Realizado</th><th>Status</th><th>Saldo acumulado</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=br_date($m['due_date'])?></td><td><span class="font-semibold <?=$m['kind']==='Entrada'?'text-emerald-600':'text-red-600'?>"><?=$m['kind']?></span></td><td class="font-medium"><?=e($m['description'])?></td><td><?=money($m['expected'])?></td><td><?=money($m['realized'])?></td><td><?=e(ucfirst($m['status']))?></td><td class="font-semibold <?=$m['balance']<0?'text-red-600':''?>"><?=money($m['balance'])?></td></tr><?php endforeach;?><?php if(!$movements):?><tr><td colspan="7" class="text-center text-slate-500">Nenhuma movimentação no período.</td></tr><?php endif;?></tbody></table></div>
